CREATE OR REPLACE FUNCTION public.adc_protect_slot()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF (NEW.clinic_id,NEW.dentist_id,NEW.starts_at,NEW.ends_at) IS DISTINCT FROM
     (OLD.clinic_id,OLD.dentist_id,OLD.starts_at,OLD.ends_at)
     AND EXISTS (SELECT 1 FROM adc_visit WHERE availability_slot_id=OLD.id) THEN
    RAISE EXCEPTION 'referenced availability identity/times are immutable in v0.3' USING ERRCODE='23514';
  END IF;
  IF NOT NEW.is_active AND EXISTS (SELECT 1 FROM adc_visit WHERE availability_slot_id=OLD.id AND status IN ('SCHEDULED','CHECKED_IN')) THEN
    RAISE EXCEPTION 'resolve unfinished bookings before disabling availability' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_cash_history_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE i adc_invoice%ROWTYPE; a adc_equipment_asset%ROWTYPE; e adc_equipment_event%ROWTYPE;
        original adc_cash_entry%ROWTYPE; amendment adc_equipment_cost_amendment%ROWTYPE; current_amendment bigint; fee numeric; clinic bigint; vstate text; vvisit bigint;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'cash history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.state<>'PENDING' OR NEW.lock_version<>0 OR NEW.review_reason<>'' THEN
      RAISE EXCEPTION 'cash entry starts as an unreviewed request' USING ERRCODE='23514';
    END IF;
  ELSE
    IF OLD.state<>'PENDING' OR NEW.state NOT IN ('POSTED','REJECTED') OR NEW.lock_version<>1
       OR (NEW.operation_id,NEW.clinic_id,NEW.invoice_id,NEW.based_record_version_id,NEW.equipment_event_id,
           NEW.equipment_cost_amendment_id,NEW.reversal_of_id,NEW.kind,NEW.amount,NEW.occurred_on,NEW.reason,NEW.prepared_by_id,NEW.prepared_at)
         IS DISTINCT FROM
          (OLD.operation_id,OLD.clinic_id,OLD.invoice_id,OLD.based_record_version_id,OLD.equipment_event_id,
           OLD.equipment_cost_amendment_id,OLD.reversal_of_id,OLD.kind,OLD.amount,OLD.occurred_on,OLD.reason,OLD.prepared_by_id,OLD.prepared_at)
       OR btrim(NEW.review_reason)='' OR NEW.reviewed_at<NEW.prepared_at THEN
      RAISE EXCEPTION 'cash request facts and terminal decisions are immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.invoice_id IS NOT NULL THEN
    SELECT * INTO i FROM adc_invoice WHERE id=NEW.invoice_id;
    SELECT clinic_id INTO clinic FROM adc_visit WHERE id=i.visit_id;
    SELECT state,visit_id INTO vstate,vvisit FROM adc_visit_record_version WHERE id=NEW.based_record_version_id;
    IF clinic IS DISTINCT FROM NEW.clinic_id OR vstate IS DISTINCT FROM 'PUBLISHED' OR vvisit IS DISTINCT FROM i.visit_id
       OR (NEW.state<>'REJECTED' AND i.current_record_version_id<>NEW.based_record_version_id) THEN
      RAISE EXCEPTION 'cash request requires its own current published bill' USING ERRCODE='23514';
    END IF;
  ELSE
    PERFORM 1 FROM adc_equipment_asset WHERE id=(SELECT asset_id FROM adc_equipment_event WHERE id=NEW.equipment_event_id) FOR UPDATE;
    SELECT * INTO e FROM adc_equipment_event WHERE id=NEW.equipment_event_id FOR UPDATE;
    SELECT * INTO a FROM adc_equipment_asset WHERE id=e.asset_id;
    fee=e.cost;
    IF NEW.equipment_cost_amendment_id IS NOT NULL THEN
      SELECT * INTO amendment FROM adc_equipment_cost_amendment WHERE id=NEW.equipment_cost_amendment_id;
      IF NOT FOUND OR amendment.event_id<>e.id OR amendment.state<>'APPROVED' THEN
        RAISE EXCEPTION 'invalid equipment cost basis' USING ERRCODE='23514';
      END IF;
      fee=amendment.proposed_cost;
    END IF;
    IF a.clinic_id IS DISTINCT FROM NEW.clinic_id OR e.kind NOT IN ('REGISTER','SERVICE')
       OR fee IS NULL OR fee<=0 OR NEW.amount<>fee THEN
      RAISE EXCEPTION 'equipment cash requires matching retained cost basis' USING ERRCODE='23514';
    END IF;
    IF NEW.state<>'REJECTED' AND NEW.reversal_of_id IS NULL THEN
      SELECT id INTO current_amendment FROM adc_equipment_cost_amendment WHERE event_id=e.id AND state='APPROVED' ORDER BY id DESC LIMIT 1;
      IF NEW.equipment_cost_amendment_id IS DISTINCT FROM current_amendment
         OR EXISTS (SELECT 1 FROM adc_equipment_cost_amendment WHERE event_id=e.id AND state='PENDING') THEN
        RAISE EXCEPTION 'equipment cost basis is stale or pending review' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  IF NEW.reversal_of_id IS NOT NULL THEN
    SELECT * INTO original FROM adc_cash_entry WHERE id=NEW.reversal_of_id;
    IF NOT FOUND OR original.state<>'POSTED' OR original.reversal_of_id IS NOT NULL OR original.amount<>NEW.amount
       OR original.clinic_id<>NEW.clinic_id OR original.invoice_id IS DISTINCT FROM NEW.invoice_id
       OR original.equipment_event_id IS DISTINCT FROM NEW.equipment_event_id
       OR original.equipment_cost_amendment_id IS DISTINCT FROM NEW.equipment_cost_amendment_id
       OR NOT ((original.kind='RECEIPT' AND NEW.kind='REFUND') OR (original.kind='REFUND' AND NEW.kind='RECEIPT')
               OR (original.kind='EQUIPMENT_EXPENSE' AND NEW.kind='EXPENSE_REVERSAL')) THEN
      RAISE EXCEPTION 'invalid cash reversal lineage' USING ERRCODE='23514';
    END IF;
  ELSIF NEW.kind='EXPENSE_REVERSAL' THEN
    RAISE EXCEPTION 'expense reversal requires its original entry' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_financial_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e adc_cash_entry%ROWTYPE; a adc_payment_account%ROWTYPE;
        p adc_cash_evidence%ROWTYPE; b adc_statement_batch%ROWTYPE;
        l adc_statement_line%ROWTYPE; latest_id bigint;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'financial evidence history cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='adc_payment_account' THEN
   IF NEW.code !~ '^[A-Z0-9][A-Z0-9_-]{1,39}$' THEN RAISE EXCEPTION 'invalid payment account code' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     IF NOT NEW.is_active OR NEW.lock_version<>0 OR NEW.last_operation_id<>NEW.operation_id THEN
       RAISE EXCEPTION 'account starts active at version zero' USING ERRCODE='23514'; END IF;
   ELSIF (to_jsonb(NEW)-ARRAY['is_active','lock_version','last_operation_id']) IS DISTINCT FROM
         (to_jsonb(OLD)-ARRAY['is_active','lock_version','last_operation_id']) OR
         NEW.is_active=OLD.is_active OR NEW.lock_version<>OLD.lock_version+1 OR NEW.last_operation_id=OLD.last_operation_id THEN
     RAISE EXCEPTION 'account identity is immutable and state changes are versioned' USING ERRCODE='23514';
   END IF;
 ELSIF TG_TABLE_NAME='adc_cash_evidence' THEN
   SELECT * INTO e FROM adc_cash_entry WHERE id=NEW.cash_entry_id;
   SELECT * INTO a FROM adc_payment_account WHERE id=NEW.account_id;
   IF a.clinic_id IS DISTINCT FROM e.clinic_id OR btrim(NEW.reference)='' OR NEW.reference<>btrim(NEW.reference) OR btrim(NEW.reason)='' THEN
     RAISE EXCEPTION 'evidence needs its own clinic account and reference' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     SELECT * INTO p FROM adc_cash_evidence WHERE cash_entry_id=NEW.cash_entry_id ORDER BY version DESC LIMIT 1;
     IF NEW.state<>'PENDING' OR (p.id IS NULL AND (NEW.version<>1 OR NEW.previous_id IS NOT NULL)) OR
        (p.id IS NOT NULL AND (NEW.previous_id IS DISTINCT FROM p.id OR NEW.version<>p.version+1 OR p.state='PENDING')) OR
        (NEW.initial AND (NEW.version<>1 OR e.state<>'PENDING' OR NEW.prepared_by_id<>e.prepared_by_id)) OR
        (NOT NEW.initial AND e.state<>'POSTED') THEN
       RAISE EXCEPTION 'evidence version lineage is invalid' USING ERRCODE='23514'; END IF;
   ELSE
     IF OLD.state<>'PENDING' OR NEW.state NOT IN ('APPROVED','REJECTED') OR
       (to_jsonb(NEW)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason']) OR NEW.reviewed_at<NEW.prepared_at OR
       (NEW.initial AND ((NEW.state='APPROVED' AND e.state<>'POSTED') OR (NEW.state='REJECTED' AND e.state<>'REJECTED'))) OR
       (NOT NEW.initial AND e.state<>'POSTED') THEN
       RAISE EXCEPTION 'evidence facts and terminal decisions are immutable' USING ERRCODE='23514'; END IF;
   END IF;
 ELSIF TG_TABLE_NAME='adc_statement_batch' THEN
   IF octet_length(NEW.source_bytes) NOT BETWEEN 1 AND 2097152 OR NEW.parser_version<>'csv-v1' OR
      jsonb_typeof(NEW.normalized_rows)<>'array' OR jsonb_array_length(NEW.normalized_rows) NOT BETWEEN 1 AND 1000 OR
      NEW.digest<>encode(sha256(NEW.source_bytes),'hex') THEN
     RAISE EXCEPTION 'invalid bounded statement evidence' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     IF NEW.state<>'DRAFT' THEN RAISE EXCEPTION 'statement starts as a private draft' USING ERRCODE='23514'; END IF;
   ELSIF OLD.state<>'DRAFT' OR NEW.state<>'IMPORTED' OR NEW.new_count+NEW.skipped_count<>jsonb_array_length(NEW.normalized_rows) OR
      NEW.imported_at<NEW.created_at OR
      (to_jsonb(NEW)-ARRAY['state','operation_id','imported_at','new_count','skipped_count']) IS DISTINCT FROM
      (to_jsonb(OLD)-ARRAY['state','operation_id','imported_at','new_count','skipped_count']) THEN
     RAISE EXCEPTION 'statement source and accepted batches are immutable' USING ERRCODE='23514';
   END IF;
 ELSIF TG_TABLE_NAME='adc_statement_line' THEN
   IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'accepted statement rows are immutable' USING ERRCODE='23514'; END IF;
   SELECT * INTO b FROM adc_statement_batch WHERE id=NEW.batch_id;
   IF b.account_id IS DISTINCT FROM NEW.account_id OR b.state<>'DRAFT' OR
      NOT (b.normalized_rows @> jsonb_build_array(jsonb_build_object('transaction_id',NEW.transaction_id,
        'booked_on',to_char(NEW.booked_on,'YYYY-MM-DD'),'direction',NEW.direction,'amount',NEW.amount::text,
        'currency',NEW.currency,'reference',NEW.reference))) THEN
     RAISE EXCEPTION 'statement line does not belong to its retained import' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='adc_reconciliation_match' THEN
   SELECT * INTO e FROM adc_cash_entry WHERE id=NEW.cash_entry_id;
   SELECT * INTO p FROM adc_cash_evidence WHERE id=NEW.evidence_id;
   SELECT * INTO l FROM adc_statement_line WHERE id=NEW.line_id;
   SELECT * INTO a FROM adc_payment_account WHERE id=l.account_id;
   SELECT id INTO latest_id FROM adc_cash_evidence WHERE cash_entry_id=NEW.cash_entry_id AND state='APPROVED' ORDER BY version DESC LIMIT 1;
   IF TG_OP='INSERT' THEN
     IF NEW.state<>'PENDING' THEN RAISE EXCEPTION 'matching starts pending independent review' USING ERRCODE='23514'; END IF;
   ELSE
     IF (to_jsonb(NEW)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason','invalidated_by_id','invalidated_at']) IS DISTINCT FROM
        (to_jsonb(OLD)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason','invalidated_by_id','invalidated_at']) THEN
       RAISE EXCEPTION 'matching source identity is immutable' USING ERRCODE='23514'; END IF;
     IF NEW.state='STALE' THEN
       IF OLD.state NOT IN ('PENDING','CONFIRMED') OR latest_id IS NULL OR latest_id=NEW.evidence_id OR
          (NEW.reviewed_by_id,NEW.reviewed_at,NEW.review_reason) IS DISTINCT FROM (OLD.reviewed_by_id,OLD.reviewed_at,OLD.review_reason) OR
          NEW.invalidated_at<NEW.prepared_at THEN
         RAISE EXCEPTION 'only new approved evidence invalidates an active match' USING ERRCODE='23514'; END IF;
     ELSIF OLD.state<>'PENDING' OR NEW.state NOT IN ('CONFIRMED','REJECTED') OR NEW.reviewed_at<NEW.prepared_at THEN
       RAISE EXCEPTION 'matching decisions are retained' USING ERRCODE='23514';
     END IF;
   END IF;
   IF NEW.state IN ('PENDING','CONFIRMED') AND
      (e.state<>'POSTED' OR p.state<>'APPROVED' OR p.cash_entry_id<>e.id OR p.id IS DISTINCT FROM latest_id OR
       p.account_id<>l.account_id OR e.clinic_id<>a.clinic_id OR e.amount<>l.amount OR l.currency<>'CNY' OR p.reference<>l.reference OR
       l.direction<>CASE WHEN e.kind IN ('RECEIPT','EXPENSE_REVERSAL') THEN 'IN' ELSE 'OUT' END OR
       NOT EXISTS(SELECT 1 FROM adc_statement_batch WHERE id=l.batch_id AND state='IMPORTED')) THEN
     RAISE EXCEPTION 'matching requires exact current approved evidence and posted cash' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_evidence_commit_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE latest_id bigint;
BEGIN
 IF TG_TABLE_NAME='adc_cash_evidence' AND NEW.state='APPROVED' THEN
   SELECT id INTO latest_id FROM adc_cash_evidence WHERE cash_entry_id=NEW.cash_entry_id AND state='APPROVED' ORDER BY version DESC LIMIT 1;
   IF EXISTS(SELECT 1 FROM adc_reconciliation_match WHERE cash_entry_id=NEW.cash_entry_id AND state IN ('PENDING','CONFIRMED') AND evidence_id<>latest_id) THEN
     RAISE EXCEPTION 'new evidence must invalidate old active matches atomically' USING ERRCODE='23514'; END IF;
 ELSIF TG_TABLE_NAME='adc_statement_batch' AND NEW.state='IMPORTED' THEN
   IF NEW.new_count<>(SELECT count(*) FROM adc_statement_line WHERE batch_id=NEW.id) THEN
     RAISE EXCEPTION 'import counts must match accepted rows' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_clinical_encounter_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
 IF TG_OP = 'DELETE' OR (to_jsonb(OLD)-'revision') IS DISTINCT FROM (to_jsonb(NEW)-'revision') THEN
  RAISE EXCEPTION 'Clinical encounter identity is retained';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_check_recall_completion()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r adc_clinical_recall%ROWTYPE; i adc_next_visit_instruction%ROWTYPE; s adc_visit%ROWTYPE; valid boolean;
BEGIN
 SELECT * INTO r FROM adc_clinical_recall WHERE id=NEW.id;
 IF r.state<>'COMPLETED' THEN RETURN NULL; END IF;
 SELECT * INTO i FROM adc_next_visit_instruction WHERE id=r.instruction_id;
 SELECT v.* INTO s FROM adc_visit v JOIN adc_clinical_encounter e ON e.visit_id=v.id JOIN adc_clinical_record_version c ON c.encounter_id=e.id WHERE c.id=i.source_record_id;
 IF i.completion_rule='EXAM_CONFIRMED' THEN
  SELECT EXISTS (SELECT 1 FROM adc_clinical_record_version c JOIN adc_clinical_encounter e ON e.id=c.encounter_id
   JOIN adc_visit v ON v.id=e.visit_id JOIN adc_resource_plan p ON p.visit_id=v.id AND p.is_current
   WHERE c.id=r.completion_record_id AND v.id<>s.id AND v.patient_id=s.patient_id AND v.clinic_id=s.clinic_id
    AND p.service_id=i.service_id AND v.status IN ('COMPLETED','CLOSED_NO_TREATMENT')
    AND c.observed_at>=i.recorded_at AND r.completed_at>=c.recorded_at AND r.completed_at>=v.completed_at) INTO valid;
 ELSIF i.completion_rule='STEP_COMPLETED' THEN
  SELECT EXISTS (SELECT 1 FROM adc_performed_procedure a JOIN adc_clinical_encounter e ON e.id=a.encounter_id
   JOIN adc_clinical_record_version c ON c.id=a.source_record_id AND c.encounter_id=e.id
   JOIN adc_visit v ON v.id=e.visit_id JOIN adc_resource_plan p ON p.visit_id=v.id AND p.is_current
   WHERE a.id=r.completion_performed_id AND a.step_version_id=i.step_version_id AND a.state='ACTIVE' AND a.progress='COMPLETE'
    AND v.id<>s.id AND v.patient_id=s.patient_id AND v.clinic_id=s.clinic_id AND p.service_id=i.service_id
    AND v.status='COMPLETED' AND a.observed_at>=i.recorded_at AND r.completed_at>=a.recorded_at AND r.completed_at>=v.completed_at) INTO valid;
 ELSE valid:=false;
 END IF;
 IF NOT valid THEN RAISE EXCEPTION 'Recall completion requires matching actual closed care evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_protect_coord_task()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'coordination task history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF OLD.state IN ('CLOSED','CANCELLED') THEN
    RAISE EXCEPTION 'terminal coordination tasks are immutable' USING ERRCODE='23514';
  END IF;
  IF (NEW.slot_id,NEW.created_by_id,NEW.created_at,NEW.purpose,NEW.opening_reason,NEW.creation_operation)
      IS DISTINCT FROM (OLD.slot_id,OLD.created_by_id,OLD.created_at,OLD.purpose,OLD.opening_reason,OLD.creation_operation) THEN
    RAISE EXCEPTION 'coordination task identity is immutable' USING ERRCODE='23514';
  END IF;
  IF NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'coordination task update requires next revision' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_protect_closed_correction()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.status<>'OPEN' THEN
    RAISE EXCEPTION 'resolved corrections are immutable' USING ERRCODE='23514';
  END IF;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_daily_close_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE prior adc_daily_close%ROWTYPE; facts jsonb; value text;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'daily close history cannot be deleted' USING ERRCODE='23514'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('adc.daily-close:' || NEW.clinic_id::text || ':' || NEW.business_date::text,0));
 IF TG_OP='INSERT' THEN
   IF NEW.state<>'PENDING' OR NEW.lock_version<>0 OR NEW.business_date>(now() AT TIME ZONE 'Asia/Shanghai')::date
      OR btrim(NEW.evidence)='' OR btrim(NEW.reason)='' THEN
     RAISE EXCEPTION 'daily close starts with current dated evidence pending review' USING ERRCODE='23514';
   END IF;
   SELECT * INTO prior FROM adc_daily_close WHERE clinic_id=NEW.clinic_id AND business_date=NEW.business_date ORDER BY version DESC LIMIT 1;
   IF NEW.previous_id IS DISTINCT FROM prior.id OR NEW.version<>coalesce(prior.version,0)+1 OR prior.state='PENDING' THEN
     RAISE EXCEPTION 'daily close requires latest terminal predecessor' USING ERRCODE='23514';
   END IF;
   IF jsonb_typeof(NEW.declared) IS DISTINCT FROM 'object' THEN
     RAISE EXCEPTION 'invalid declared amounts' USING ERRCODE='23514';
   END IF;
   IF NOT (NEW.declared ?& ARRAY['RECEIPT','REFUND','EQUIPMENT_EXPENSE','EXPENSE_REVERSAL'])
      OR (SELECT count(*) FROM jsonb_object_keys(NEW.declared))<>4 THEN
     RAISE EXCEPTION 'all four independent amounts required' USING ERRCODE='23514';
   END IF;
   FOR value IN SELECT jsonb_each_text.value FROM jsonb_each_text(NEW.declared) LOOP
     IF value IS NULL OR value !~ '^(0|[1-9][0-9]{0,25})\.[0-9]{2}$' THEN
       RAISE EXCEPTION 'invalid declared amount format' USING ERRCODE='23514';
     END IF;
   END LOOP;
 ELSE
   IF OLD.state<>'PENDING' OR NEW.state NOT IN ('APPROVED','REJECTED') OR NEW.lock_version<>1
      OR (NEW.operation_id,NEW.clinic_id,NEW.business_date,NEW.version,NEW.previous_id,NEW.snapshot,NEW.declared,NEW.evidence,NEW.reason,NEW.prepared_by_id,NEW.prepared_at)
        IS DISTINCT FROM (OLD.operation_id,OLD.clinic_id,OLD.business_date,OLD.version,OLD.previous_id,OLD.snapshot,OLD.declared,OLD.evidence,OLD.reason,OLD.prepared_by_id,OLD.prepared_at)
      OR btrim(NEW.review_reason)='' OR NEW.reviewed_at<NEW.prepared_at THEN
      RAISE EXCEPTION 'daily close facts and terminal decisions are immutable' USING ERRCODE='23514';
   END IF;
 END IF;
 IF TG_OP='INSERT' OR NEW.state='APPROVED' THEN
   facts=adc_daily_facts(NEW.clinic_id,NEW.business_date);
   IF NEW.snapshot IS DISTINCT FROM facts THEN RAISE EXCEPTION 'daily close snapshot stale' USING ERRCODE='23514'; END IF;
   IF NEW.state='APPROVED' AND ((facts->>'pending')::bigint<>0 OR NEW.declared IS DISTINCT FROM facts->'totals') THEN
      RAISE EXCEPTION 'unresolved daily discrepancy or pending cash' USING ERRCODE='23514';
   END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_equipment_asset_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'equipment history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF (NEW.clinic_id,NEW.asset_code,NEW.name,NEW.category,NEW.location,NEW.acquired_on,NEW.acquisition_cost,NEW.registered_by_id,NEW.registered_at)
      IS DISTINCT FROM
     (OLD.clinic_id,OLD.asset_code,OLD.name,OLD.category,OLD.location,OLD.acquired_on,OLD.acquisition_cost,OLD.registered_by_id,OLD.registered_at)
      OR OLD.state='RETIRED' OR NEW.lock_version<>OLD.lock_version+1 THEN
    RAISE EXCEPTION 'equipment identity or revision is immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_equipment_final_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a adc_equipment_asset%ROWTYPE; n bigint;
BEGIN
  SELECT * INTO a FROM adc_equipment_asset WHERE id=NEW.id;
  SELECT count(*) INTO n FROM adc_equipment_event WHERE asset_id=a.id;
  IF n<>a.lock_version+1 OR NOT EXISTS (
    SELECT 1 FROM adc_equipment_event WHERE asset_id=a.id AND sequence=a.lock_version
      AND next_state=a.state AND next_service_due IS NOT DISTINCT FROM a.next_service_due) THEN
    RAISE EXCEPTION 'equipment update requires matching retained event' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_maintenance_final_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o adc_maintenance_order%ROWTYPE; a adc_equipment_asset%ROWTYPE; source adc_equipment_event%ROWTYPE;
        step adc_maintenance_action%ROWTYPE; service adc_equipment_event%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='adc_equipment_asset' THEN
  SELECT * INTO a FROM adc_equipment_asset WHERE id=NEW.id;
  IF EXISTS (SELECT 1 FROM adc_maintenance_order w JOIN adc_equipment_event e ON e.id=w.maintenance_event_id
      WHERE w.asset_id=a.id AND w.state IN ('ASSIGNED','IN_PROGRESS','READY') AND
       (a.state<>'MAINTENANCE' OR a.lock_version<>e.sequence)) THEN
   RAISE EXCEPTION 'finish maintenance responsibility before changing equipment state' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM adc_equipment_event e JOIN adc_equipment_event stop ON stop.asset_id=e.asset_id AND stop.sequence=e.sequence-1
      WHERE e.asset_id=a.id AND e.sequence=a.lock_version AND e.kind='SERVICE' AND e.previous_state='MAINTENANCE'
       AND EXISTS (SELECT 1 FROM adc_maintenance_order w WHERE w.maintenance_event_id=stop.id)
       AND NOT EXISTS (SELECT 1 FROM adc_maintenance_order w WHERE w.maintenance_event_id=stop.id AND w.state='CLOSED' AND w.service_event_id=e.id)) THEN
   RAISE EXCEPTION 'managed repair requires independent acceptance even after cancellation' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
 SELECT * INTO o FROM adc_maintenance_order WHERE id=NEW.id;
 SELECT * INTO a FROM adc_equipment_asset WHERE id=o.asset_id;
 SELECT * INTO source FROM adc_equipment_event WHERE id=o.maintenance_event_id;
 SELECT * INTO step FROM adc_maintenance_action WHERE order_id=o.id AND sequence=o.lock_version;
 IF NOT FOUND OR step.snapshot IS DISTINCT FROM adc_maintenance_snapshot(o) THEN
  RAISE EXCEPTION 'maintenance requires matching retained action' USING ERRCODE='23514';
 END IF;
 IF o.state IN ('ASSIGNED','IN_PROGRESS','READY') AND (a.state<>'MAINTENANCE' OR a.lock_version<>source.sequence) THEN
  RAISE EXCEPTION 'open maintenance source no longer current' USING ERRCODE='23514';
 END IF;
 IF o.state='CLOSED' THEN
  SELECT * INTO service FROM adc_equipment_event WHERE id=o.service_event_id;
  IF NOT FOUND OR service.asset_id<>o.asset_id OR service.sequence<>source.sequence+1 OR service.kind<>'SERVICE'
    OR service.previous_state<>'MAINTENANCE' OR service.next_state<>'IN_SERVICE' OR service.recorded_by_id<>o.reviewed_by_id
    OR (service.performed_on,service.cost,service.next_service_due,service.note,service.operation_id)
     IS DISTINCT FROM (o.performed_on,o.cost,o.next_service_due,o.completion_note,step.operation_id) THEN
   RAISE EXCEPTION 'accepted maintenance requires exact service event linkage' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_equipment_cost_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e adc_equipment_event%ROWTYPE; latest adc_equipment_cost_amendment%ROWTYPE; fee numeric; net numeric;
BEGIN
  IF TG_OP='DELETE' THEN
    RAISE EXCEPTION 'cost history cannot be deleted' USING ERRCODE='23514';
  END IF;
  PERFORM 1 FROM adc_equipment_asset WHERE id=(SELECT asset_id FROM adc_equipment_event WHERE id=NEW.event_id) FOR UPDATE;
  SELECT * INTO e FROM adc_equipment_event WHERE id=NEW.event_id FOR UPDATE;
  IF NOT FOUND OR e.kind NOT IN ('REGISTER','SERVICE') OR btrim(NEW.reason)='' THEN
    RAISE EXCEPTION 'invalid equipment fee event or reason' USING ERRCODE='23514';
  END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.state<>'PENDING' OR NEW.lock_version<>0 OR NEW.review_reason<>'' THEN
      RAISE EXCEPTION 'cost amendment starts pending' USING ERRCODE='23514';
    END IF;
  ELSE
    IF OLD.state<>'PENDING' OR NEW.state NOT IN ('APPROVED','REJECTED') OR NEW.lock_version<>1
       OR (NEW.event_id,NEW.operation_id,NEW.based_amendment_id,NEW.previous_cost,NEW.proposed_cost,NEW.reason,NEW.prepared_by_id,NEW.prepared_at)
          IS DISTINCT FROM (OLD.event_id,OLD.operation_id,OLD.based_amendment_id,OLD.previous_cost,OLD.proposed_cost,OLD.reason,OLD.prepared_by_id,OLD.prepared_at)
       OR btrim(NEW.review_reason)='' OR NEW.reviewed_at<NEW.prepared_at THEN
      RAISE EXCEPTION 'cost facts and terminal decisions are immutable' USING ERRCODE='23514';
    END IF;
  END IF;
  IF NEW.state<>'REJECTED' THEN
    SELECT * INTO latest FROM adc_equipment_cost_amendment WHERE event_id=e.id AND state='APPROVED' ORDER BY id DESC LIMIT 1;
    fee=CASE WHEN latest.id IS NULL THEN e.cost ELSE latest.proposed_cost END;
    IF NEW.based_amendment_id IS DISTINCT FROM latest.id OR NEW.previous_cost IS DISTINCT FROM fee OR NEW.proposed_cost IS NOT DISTINCT FROM fee THEN
      RAISE EXCEPTION 'cost amendment requires current distinct basis' USING ERRCODE='23514';
    END IF;
    SELECT coalesce(sum(CASE WHEN kind='EQUIPMENT_EXPENSE' THEN amount ELSE -amount END),0) INTO net
      FROM adc_cash_entry WHERE equipment_event_id=e.id AND state='POSTED';
    IF net<>0 OR EXISTS (SELECT 1 FROM adc_cash_entry WHERE equipment_event_id=e.id AND state='PENDING') THEN
      RAISE EXCEPTION 'resolve pending cash and reverse posted fees first' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_equipment_event_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a adc_equipment_asset%ROWTYPE; p adc_equipment_event%ROWTYPE;
BEGIN
  IF TG_OP<>'INSERT' THEN
    RAISE EXCEPTION 'equipment events are append-only' USING ERRCODE='23514';
  END IF;
  SELECT * INTO a FROM adc_equipment_asset WHERE id=NEW.asset_id FOR UPDATE;
  IF NOT FOUND OR NEW.sequence<>a.lock_version OR NEW.next_state<>a.state
      OR NEW.next_service_due IS DISTINCT FROM a.next_service_due
      OR NEW.performed_on>(current_timestamp AT TIME ZONE 'Asia/Shanghai')::date THEN
    RAISE EXCEPTION 'equipment event and current asset disagree' USING ERRCODE='23514';
  END IF;
  IF NEW.sequence=0 THEN
    IF NEW.kind<>'REGISTER' OR NEW.previous_state<>'' OR NEW.next_state<>'IN_SERVICE'
       OR NEW.performed_on<>a.acquired_on OR NEW.cost IS DISTINCT FROM a.acquisition_cost
       OR NEW.recorded_by_id<>a.registered_by_id THEN
      RAISE EXCEPTION 'invalid equipment registration event' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO p FROM adc_equipment_event WHERE asset_id=a.id AND sequence=NEW.sequence-1;
    IF NOT FOUND OR NEW.previous_state<>p.next_state OR NEW.performed_on<p.performed_on
       OR NOT ((NEW.kind='MAINTENANCE' AND p.next_state='IN_SERVICE' AND NEW.next_state='MAINTENANCE')
           OR (NEW.kind='SERVICE' AND p.next_state IN ('IN_SERVICE','MAINTENANCE') AND NEW.next_state='IN_SERVICE')
           OR (NEW.kind='RETIRE' AND p.next_state IN ('IN_SERVICE','MAINTENANCE') AND NEW.next_state='RETIRED')) THEN
      RAISE EXCEPTION 'invalid equipment transition history' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_inbox_ownership()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'inbox history cannot be deleted' USING ERRCODE='23514';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (SELECT 1 FROM adc_role_assignment r JOIN adc_notification_outbox e ON e.id=NEW.event_id
       WHERE r.id=NEW.grant_id AND r.user_id=NEW.recipient_id AND r.role=NEW.role
       AND r.clinic_id=NEW.clinic_id AND r.scope_kind='CLINIC' AND e.clinic_id=NEW.clinic_id
       AND e.recipients @> jsonb_build_array(jsonb_build_object('user_id',NEW.recipient_id,'grant_id',NEW.grant_id,'role',NEW.role))) THEN
      RAISE EXCEPTION 'inbox recipient does not match original event scope' USING ERRCODE='23514';
    END IF;
  ELSIF (NEW.event_id,NEW.recipient_id,NEW.grant_id,NEW.clinic_id,NEW.role,NEW.delivered_at)
        IS DISTINCT FROM (OLD.event_id,OLD.recipient_id,OLD.grant_id,OLD.clinic_id,OLD.role,OLD.delivered_at)
        OR (OLD.read_at IS NOT NULL AND NEW.read_at IS DISTINCT FROM OLD.read_at) THEN
    RAISE EXCEPTION 'inbox ownership and first acknowledgement are immutable' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_check_visit_final()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE old_visit bigint; new_visit bigint; parent_id bigint;
BEGIN
  IF TG_TABLE_NAME='adc_visit' THEN
    IF TG_OP<>'INSERT' THEN old_visit=OLD.id; END IF;
    IF TG_OP<>'DELETE' THEN new_visit=NEW.id; END IF;
  ELSIF TG_TABLE_NAME='adc_treatment_record' THEN
    IF TG_OP<>'INSERT' THEN SELECT visit_id INTO old_visit FROM adc_visit_record_version WHERE id=OLD.record_version_id; END IF;
    IF TG_OP<>'DELETE' THEN SELECT visit_id INTO new_visit FROM adc_visit_record_version WHERE id=NEW.record_version_id; END IF;
  ELSE
    IF TG_OP<>'INSERT' THEN old_visit=OLD.visit_id; END IF;
    IF TG_OP<>'DELETE' THEN new_visit=NEW.visit_id; END IF;
  END IF;
  IF old_visit IS NOT NULL THEN PERFORM adc_validate_visit(old_visit); END IF;
  IF new_visit IS NOT NULL AND new_visit IS DISTINCT FROM old_visit THEN PERFORM adc_validate_visit(new_visit); END IF;
  -- Inserting a successor must also validate the predecessor at the same commit.
  IF TG_TABLE_NAME='adc_visit' THEN
    IF TG_OP<>'DELETE' THEN
      IF NEW.replaces_visit_id IS NOT NULL THEN
        PERFORM adc_validate_visit(NEW.replaces_visit_id);
      END IF;
    END IF;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_validate_correction_publication()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE r adc_visit_record_version%ROWTYPE; c adc_correction_request%ROWTYPE;
BEGIN
  SELECT * INTO r FROM adc_visit_record_version WHERE id=NEW.current_record_version_id;
  IF r.previous_version_id IS NULL THEN
    IF r.revision_no<>1 OR r.correction_request_id IS NOT NULL THEN
      RAISE EXCEPTION 'first publication must be revision one' USING ERRCODE='23514';
    END IF;
  ELSE
    SELECT * INTO c FROM adc_correction_request WHERE id=r.correction_request_id;
    IF NOT FOUND OR c.status<>'APPLIED' OR c.visit_id<>NEW.visit_id OR c.base_record_version_id<>r.previous_version_id
       OR c.reviewer_id IS NULL OR c.reviewer_id=c.requester_id OR r.reviewed_by_id IS NULL OR r.reviewed_by_id<>c.reviewer_id THEN
      RAISE EXCEPTION 'correction requires a matching independent approval' USING ERRCODE='23514';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM adc_visit_record_version p WHERE p.id=r.previous_version_id AND p.visit_id=r.visit_id AND p.revision_no<r.revision_no AND p.state='PUBLISHED') THEN
      RAISE EXCEPTION 'invalid predecessor revision' USING ERRCODE='23514';
    END IF;
  END IF;
  IF TG_OP='UPDATE' AND NEW.current_record_version_id<>OLD.current_record_version_id THEN
    IF r.previous_version_id IS DISTINCT FROM OLD.current_record_version_id THEN
      RAISE EXCEPTION 'current invoice must advance from its current revision' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_check_lab_acceptance()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE c adc_lab_case%ROWTYPE; valid boolean;
BEGIN
 SELECT * INTO c FROM adc_lab_case WHERE id=NEW.id;
 IF c.state<>'ACCEPTED' THEN RETURN NULL; END IF;
 SELECT EXISTS (SELECT 1 FROM adc_lab_review r JOIN adc_plan_step_version t ON t.id=r.target_step_version_id
  JOIN adc_plan_step_version o ON o.id=c.step_version_id WHERE r.case_id=c.id AND r.cycle=c.cycle AND r.decision='ACCEPTED'
   AND t.step_id=o.step_id AND t.treatment_type_id=o.treatment_type_id AND t.service_id=o.service_id
   AND t.tooth IS NOT DISTINCT FROM o.tooth AND t.surface=o.surface
   AND r.id=(SELECT max(x.id) FROM adc_lab_review x WHERE x.case_id=c.id AND x.cycle=c.cycle)) INTO valid;
 IF NOT valid THEN RAISE EXCEPTION 'Lab acceptance requires an explicit current-cycle clinical review' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_maintenance_action_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o adc_maintenance_order%ROWTYPE; p adc_maintenance_action%ROWTYPE; oldstate text; oldowner bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'maintenance action immutable' USING ERRCODE='23514'; END IF;
 SELECT * INTO o FROM adc_maintenance_order WHERE id=NEW.order_id;
 IF NOT FOUND OR NEW.sequence<>o.lock_version OR NEW.snapshot IS DISTINCT FROM adc_maintenance_snapshot(o) OR btrim(NEW.note)='' THEN
  RAISE EXCEPTION 'maintenance action must match current projection' USING ERRCODE='23514';
 END IF;
 IF NEW.sequence=0 THEN
  IF NEW.action<>'OPEN' OR o.state<>'ASSIGNED' OR NEW.actor_id<>o.created_by_id THEN
   RAISE EXCEPTION 'maintenance requires original open action' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT * INTO p FROM adc_maintenance_action WHERE order_id=o.id AND sequence=NEW.sequence-1;
  oldstate=p.snapshot->>'state';oldowner=(p.snapshot->>'owner')::bigint;
  IF NOT FOUND OR NOT ((NEW.action='START' AND oldstate='ASSIGNED' AND o.state='IN_PROGRESS')
    OR (NEW.action='ASSIGN' AND oldstate IN ('ASSIGNED','IN_PROGRESS') AND o.state='ASSIGNED')
    OR (NEW.action='SUBMIT' AND oldstate='IN_PROGRESS' AND o.state='READY')
    OR (NEW.action IN ('RETURN','WITHDRAW') AND oldstate='READY' AND o.state='IN_PROGRESS')
    OR (NEW.action='APPROVE' AND oldstate='READY' AND o.state='CLOSED')
    OR (NEW.action='CANCEL' AND oldstate IN ('ASSIGNED','IN_PROGRESS') AND o.state='CANCELLED')) THEN
   RAISE EXCEPTION 'maintenance action sequence invalid' USING ERRCODE='23514';
  END IF;
  IF NEW.action<>'ASSIGN' AND (NEW.snapshot->'owner',NEW.snapshot->'due') IS DISTINCT FROM (p.snapshot->'owner',p.snapshot->'due') THEN
   RAISE EXCEPTION 'responsibility changes require assignment action' USING ERRCODE='23514';
  END IF;
  IF NEW.action='ASSIGN' AND (NEW.snapshot->'owner',NEW.snapshot->'due') IS NOT DISTINCT FROM (p.snapshot->'owner',p.snapshot->'due') THEN
   RAISE EXCEPTION 'assignment must change responsibility or deadline' USING ERRCODE='23514';
  END IF;
  IF (NEW.action IN ('START','SUBMIT','WITHDRAW') AND NEW.actor_id<>oldowner)
     OR (NEW.action IN ('RETURN','APPROVE') AND NEW.actor_id=oldowner)
     OR (NEW.action='SUBMIT' AND NEW.actor_id<>o.submitted_by_id)
     OR (NEW.action='APPROVE' AND (NEW.actor_id<>o.reviewed_by_id OR NEW.note<>o.review_reason)) THEN
   RAISE EXCEPTION 'maintenance owner and independent reviewer mismatch' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_maintenance_final_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE o adc_maintenance_order%ROWTYPE; a adc_equipment_asset%ROWTYPE; source adc_equipment_event%ROWTYPE;
        step adc_maintenance_action%ROWTYPE; service adc_equipment_event%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='adc_equipment_asset' THEN
  SELECT * INTO a FROM adc_equipment_asset WHERE id=NEW.id;
  IF EXISTS (SELECT 1 FROM adc_maintenance_order w JOIN adc_equipment_event e ON e.id=w.maintenance_event_id
      WHERE w.asset_id=a.id AND w.state IN ('ASSIGNED','IN_PROGRESS','READY') AND
       (a.state<>'MAINTENANCE' OR a.lock_version<>e.sequence)) THEN
   RAISE EXCEPTION 'finish maintenance responsibility before changing equipment state' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT 1 FROM adc_equipment_event e JOIN adc_equipment_event stop ON stop.asset_id=e.asset_id AND stop.sequence=e.sequence-1
      WHERE e.asset_id=a.id AND e.sequence=a.lock_version AND e.kind='SERVICE' AND e.previous_state='MAINTENANCE'
       AND EXISTS (SELECT 1 FROM adc_maintenance_order w WHERE w.maintenance_event_id=stop.id)
       AND NOT EXISTS (SELECT 1 FROM adc_maintenance_order w WHERE w.maintenance_event_id=stop.id AND w.state='CLOSED' AND w.service_event_id=e.id)) THEN
   RAISE EXCEPTION 'managed repair requires independent acceptance even after cancellation' USING ERRCODE='23514';
  END IF;
  RETURN NULL;
 END IF;
 SELECT * INTO o FROM adc_maintenance_order WHERE id=NEW.id;
 SELECT * INTO a FROM adc_equipment_asset WHERE id=o.asset_id;
 SELECT * INTO source FROM adc_equipment_event WHERE id=o.maintenance_event_id;
 SELECT * INTO step FROM adc_maintenance_action WHERE order_id=o.id AND sequence=o.lock_version;
 IF NOT FOUND OR step.snapshot IS DISTINCT FROM adc_maintenance_snapshot(o) THEN
  RAISE EXCEPTION 'maintenance requires matching retained action' USING ERRCODE='23514';
 END IF;
 IF o.state IN ('ASSIGNED','IN_PROGRESS','READY') AND (a.state<>'MAINTENANCE' OR a.lock_version<>source.sequence) THEN
  RAISE EXCEPTION 'open maintenance source no longer current' USING ERRCODE='23514';
 END IF;
 IF o.state='CLOSED' THEN
  SELECT * INTO service FROM adc_equipment_event WHERE id=o.service_event_id;
  IF NOT FOUND OR service.asset_id<>o.asset_id OR service.sequence<>source.sequence+1 OR service.kind<>'SERVICE'
    OR service.previous_state<>'MAINTENANCE' OR service.next_state<>'IN_SERVICE' OR service.recorded_by_id<>o.reviewed_by_id
    OR (service.performed_on,service.cost,service.next_service_due,service.note,service.operation_id)
     IS DISTINCT FROM (o.performed_on,o.cost,o.next_service_due,o.completion_note,step.operation_id) THEN
   RAISE EXCEPTION 'accepted maintenance requires exact service event linkage' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.adc_maintenance_order_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE a adc_equipment_asset%ROWTYPE; source adc_equipment_event%ROWTYPE;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'maintenance history cannot be deleted' USING ERRCODE='23514'; END IF;
 SELECT * INTO a FROM adc_equipment_asset WHERE id=NEW.asset_id FOR UPDATE;
 SELECT * INTO source FROM adc_equipment_event WHERE id=NEW.maintenance_event_id;
 IF source.asset_id IS DISTINCT FROM a.id OR source.kind IS DISTINCT FROM 'MAINTENANCE' OR btrim(NEW.issue)='' THEN
  RAISE EXCEPTION 'maintenance requires its own stop-use source' USING ERRCODE='23514';
 END IF;
 IF TG_OP='INSERT' THEN
  IF NEW.state<>'ASSIGNED' OR NEW.lock_version<>0 OR a.state<>'MAINTENANCE' OR a.lock_version<>source.sequence
     OR NEW.due_on<(now() AT TIME ZONE 'Asia/Shanghai')::date THEN
   RAISE EXCEPTION 'maintenance must start assigned against current stop-use source' USING ERRCODE='23514';
  END IF;
 ELSE
  IF OLD.state IN ('CLOSED','CANCELLED') OR NEW.lock_version<>OLD.lock_version+1
     OR (NEW.asset_id,NEW.maintenance_event_id,NEW.issue,NEW.created_by_id,NEW.created_at)
        IS DISTINCT FROM (OLD.asset_id,OLD.maintenance_event_id,OLD.issue,OLD.created_by_id,OLD.created_at)
     OR NOT ((OLD.state='ASSIGNED' AND NEW.state IN ('ASSIGNED','IN_PROGRESS','CANCELLED'))
       OR (OLD.state='IN_PROGRESS' AND NEW.state IN ('ASSIGNED','READY','CANCELLED'))
       OR (OLD.state='READY' AND NEW.state IN ('IN_PROGRESS','CLOSED'))) THEN
   RAISE EXCEPTION 'invalid maintenance transition or immutable origin' USING ERRCODE='23514';
  END IF;
  IF (NEW.assigned_to_id,NEW.due_on) IS DISTINCT FROM (OLD.assigned_to_id,OLD.due_on) AND
     (NEW.state<>'ASSIGNED' OR NEW.due_on<(now() AT TIME ZONE 'Asia/Shanghai')::date) THEN
   RAISE EXCEPTION 'assignment requires explicit new current deadline' USING ERRCODE='23514';
  END IF;
  IF NEW.state='CLOSED' AND ((NEW.performed_on,NEW.cost,NEW.next_service_due,NEW.completion_note,NEW.schedule_checked,NEW.submitted_by_id,NEW.submitted_at)
       IS DISTINCT FROM (OLD.performed_on,OLD.cost,OLD.next_service_due,OLD.completion_note,OLD.schedule_checked,OLD.submitted_by_id,OLD.submitted_at)
       OR btrim(NEW.review_reason)='' OR NEW.reviewed_at<NEW.submitted_at) THEN
   RAISE EXCEPTION 'acceptance must retain submitted repair evidence' USING ERRCODE='23514';
  END IF;
 END IF;
 IF NEW.state IN ('READY','CLOSED') AND
    (NEW.performed_on<source.performed_on OR NEW.performed_on>(now() AT TIME ZONE 'Asia/Shanghai')::date
     OR NEW.next_service_due<=NEW.performed_on OR btrim(NEW.completion_note)='' OR NEW.submitted_at<NEW.created_at) THEN
  RAISE EXCEPTION 'invalid repair facts' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_notice_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'notification event history is immutable' USING ERRCODE='23514';
  END IF;
  IF (NEW.source_event_id, NEW.task_id, NEW.clinic_id, NEW.task_revision, NEW.action,
      NEW.event_state, NEW.occurred_at, NEW.recipients)
    IS DISTINCT FROM
     (OLD.source_event_id, OLD.task_id, OLD.clinic_id, OLD.task_revision, OLD.action,
      OLD.event_state, OLD.occurred_at, OLD.recipients) THEN
    RAISE EXCEPTION 'notification source and targets are immutable' USING ERRCODE='23514';
  END IF;
  IF OLD.state IN ('DELIVERED','NO_RECIPIENTS') THEN
    RAISE EXCEPTION 'completed notification outcome cannot be rewritten' USING ERRCODE='23514';
  END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.adc_financial_evidence_guard()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE e adc_cash_entry%ROWTYPE; a adc_payment_account%ROWTYPE;
        p adc_cash_evidence%ROWTYPE; b adc_statement_batch%ROWTYPE;
        l adc_statement_line%ROWTYPE; latest_id bigint;
BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'financial evidence history cannot be deleted' USING ERRCODE='23514'; END IF;
 IF TG_TABLE_NAME='adc_payment_account' THEN
   IF NEW.code !~ '^[A-Z0-9][A-Z0-9_-]{1,39}$' THEN RAISE EXCEPTION 'invalid payment account code' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     IF NOT NEW.is_active OR NEW.lock_version<>0 OR NEW.last_operation_id<>NEW.operation_id THEN
       RAISE EXCEPTION 'account starts active at version zero' USING ERRCODE='23514'; END IF;
   ELSIF (to_jsonb(NEW)-ARRAY['is_active','lock_version','last_operation_id']) IS DISTINCT FROM
         (to_jsonb(OLD)-ARRAY['is_active','lock_version','last_operation_id']) OR
         NEW.is_active=OLD.is_active OR NEW.lock_version<>OLD.lock_version+1 OR NEW.last_operation_id=OLD.last_operation_id THEN
     RAISE EXCEPTION 'account identity is immutable and state changes are versioned' USING ERRCODE='23514';
   END IF;
 ELSIF TG_TABLE_NAME='adc_cash_evidence' THEN
   SELECT * INTO e FROM adc_cash_entry WHERE id=NEW.cash_entry_id;
   SELECT * INTO a FROM adc_payment_account WHERE id=NEW.account_id;
   IF a.clinic_id IS DISTINCT FROM e.clinic_id OR btrim(NEW.reference)='' OR NEW.reference<>btrim(NEW.reference) OR btrim(NEW.reason)='' THEN
     RAISE EXCEPTION 'evidence needs its own clinic account and reference' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     SELECT * INTO p FROM adc_cash_evidence WHERE cash_entry_id=NEW.cash_entry_id ORDER BY version DESC LIMIT 1;
     IF NEW.state<>'PENDING' OR (p.id IS NULL AND (NEW.version<>1 OR NEW.previous_id IS NOT NULL)) OR
        (p.id IS NOT NULL AND (NEW.previous_id IS DISTINCT FROM p.id OR NEW.version<>p.version+1 OR p.state='PENDING')) OR
        (NEW.initial AND (NEW.version<>1 OR e.state<>'PENDING' OR NEW.prepared_by_id<>e.prepared_by_id)) OR
        (NOT NEW.initial AND e.state<>'POSTED') THEN
       RAISE EXCEPTION 'evidence version lineage is invalid' USING ERRCODE='23514'; END IF;
   ELSE
     IF OLD.state<>'PENDING' OR NEW.state NOT IN ('APPROVED','REJECTED') OR
       (to_jsonb(NEW)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason']) IS DISTINCT FROM
       (to_jsonb(OLD)-ARRAY['state','reviewed_by_id','reviewed_at','review_reason']) OR NEW.reviewed_at<NEW.prepared_at OR
       (NEW.initial AND ((NEW.state='APPROVED' AND e.state<>'POSTED') OR (NEW.state='REJECTED' AND e.state<>'REJECTED'))) OR
       (NOT NEW.initial AND e.state<>'POSTED') THEN
       RAISE EXCEPTION 'evidence facts and terminal decisions are immutable' USING ERRCODE='23514'; END IF;
   END IF;
 ELSIF TG_TABLE_NAME='adc_statement_batch' THEN
   IF octet_length(NEW.source_bytes) NOT BETWEEN 1 AND 2097152 OR NEW.parser_version<>'csv-v1' OR
      jsonb_typeof(NEW.normalized_rows)<>'array' OR jsonb_array_length(NEW.normalized_rows) NOT BETWEEN 1 AND 1000 OR
      NEW.digest<>encode(sha256(NEW.source_bytes),'hex') THEN
     RAISE EXCEPTION 'invalid bounded statement evidence' USING ERRCODE='23514'; END IF;
   IF TG_OP='INSERT' THEN
     IF NEW.state<>'DRAFT' THEN RAISE EXCEPTION 'statement starts as a private draft' USING ERRCODE='23514'; END IF;
   ELSIF OLD.state<>'DRAFT' OR NEW.state<>'IMPORTED' OR NEW.new_count+NEW.skipped_count<>jsonb_array_length(NEW.normalized_rows) OR
      NEW.imported_at<NEW.created_at OR
